import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, sin } from 'three/tsl';
import { gsap } from 'gsap';

function hexToVec3(hex) {
  const value = String(hex || '#000000').replace('#', '');
  const normalized = value.length === 3
    ? value.split('').map((v) => v + v).join('')
    : value;
  const number = Number.parseInt(normalized, 16);
  return vec3(
    ((number >> 16) & 255) / 255,
    ((number >> 8) & 255) / 255,
    (number & 255) / 255
  );
}

function disposeOwned(root, ownedMaterials, ownedGeometries, loadedTextures) {
  for (const geometry of ownedGeometries) geometry.dispose();
  for (const material of ownedMaterials) material.dispose();
  for (const texture of loadedTextures) texture.dispose();

  root.traverse((child) => {
    if (child.userData && child !== root) {
      child.userData.handlers = undefined;
    }
  });
}

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color
  } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const root = new Group();
  root.name = config.id || 'pricing-card-1';
  root.userData.handlers = {};

  const ownedMaterials = [];
  const ownedGeometries = [];
  const loadedTextures = [];
  const timelines = [];
  const primitiveCleanups = [];

  const makeBasic = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const makePlane = (width, height, material, z) => {
    const geometry = new PlaneGeometry(width, height);
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, material);
    mesh.position.z = z;
    root.add(mesh);
    return mesh;
  };

  const backdropMaterial = makeBasic();
  const backdropUv = uv();
  const backdropGradient = mix(
    hexToVec3(surface),
    hexToVec3(ink),
    smoothstep(0.0, 1.0, backdropUv.y)
  );
  const backdropGrain = sin(
    backdropUv.x.mul(190.0).add(backdropUv.y.mul(137.0))
  ).mul(0.006);
  backdropMaterial.colorNode = backdropGradient.add(vec3(backdropGrain));

  makePlane(3.35, 2.2, backdropMaterial, -0.16);

  const shadowMaterial = makeBasic({
    color: new Color(surface),
    transparent: true,
    opacity: 0.46,
    depthWrite: false
  });
  const shadowGeometry = new CircleGeometry(1.48, 48);
  ownedGeometries.push(shadowGeometry);
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.scale.set(1.55, 0.28, 1);
  shadow.position.set(0, -0.78, -0.11);
  root.add(shadow);

  const cardMaterial = makeBasic();
  const cardUv = uv();
  const upper = mix(
    hexToVec3(ink),
    hexToVec3(paper),
    smoothstep(0.42, 1.0, cardUv.y)
  );
  const lower = mix(
    hexToVec3(surface),
    hexToVec3(ink),
    smoothstep(0.0, 0.58, cardUv.y)
  );
  const cardGradient = mix(lower, upper, smoothstep(0.18, 0.86, cardUv.y));
  const cardGrain = sin(
    cardUv.x.mul(230.0).add(cardUv.y.mul(171.0))
  ).mul(0.009);
  cardMaterial.colorNode = cardGradient.add(vec3(cardGrain));
  makePlane(2.84, 1.62, cardMaterial, -0.015);

  const frameMaterial = makeBasic({ color: new Color(paper) });
  const framePieces = [
    [2.9, 0.025, 0, 0.82, 0.025],
    [2.9, 0.025, 0, -0.82, 0.025],
    [0.025, 1.64, -1.45, 0, 0.025],
    [0.025, 1.64, 1.45, 0, 0.025]
  ];

  for (const [width, height, x, y, z] of framePieces) {
    const geometry = new BoxGeometry(width, height, 0.025);
    ownedGeometries.push(geometry);
    const mesh = new Mesh(geometry, frameMaterial);
    mesh.position.set(x, y, z);
    root.add(mesh);
  }

  const accentMaterial = makeBasic({ color: new Color(accent) });
  const accentGeometry = new BoxGeometry(0.68, 0.045, 0.035);
  ownedGeometries.push(accentGeometry);
  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.position.set(-0.98, 0.45, 0.07);
  root.add(accentBar);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let textOffset = 0.03;

  for (const item of items) {
    const text = typeof item?.text === 'string' ? item.text : '';
    if (!text) continue;

    const typography = item.typography || {};
    const textObject = ctx.fontAtlas.createText(text, {
      fontSize: typography.fontSize || 39,
      color: paper,
      align: 'left',
      letterSpacingPx: item.role === 'label' ? 3 : 0
    });

    textObject.position.set(-1.12, textOffset, 0.085);
    root.add(textObject);
    textOffset -= item.role === 'headline' ? 0.3 : 0.2;
  }

  if (config.imageUrl && ctx.textureLoader?.loadTexture) {
    const imageMaterial = makeBasic({
      transparent: true,
      opacity: 0.085,
      depthWrite: false
    });
    const imageGeometry = new PlaneGeometry(1.55, 1.55);
    ownedGeometries.push(imageGeometry);
    const imageMesh = new Mesh(imageGeometry, imageMaterial);
    imageMesh.position.set(0.72, -0.02, 0.06);
    imageMesh.rotation.z = -0.18;
    root.add(imageMesh);

    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (!root.parent && root.userData.cleaned) {
        texture.dispose();
        return;
      }
      loadedTextures.push(texture);
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.scale,
    { x: 0.97, y: 0.97, z: 0.97 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  ).to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.48, ease: 'power4.out' }
  );
  timelines.push(entrance);

  const primitives = config.cinematicPrimitives || [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler !== 'function') continue;
    const result = handler(root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (typeof result?.cleanup === 'function') primitiveCleanups.push(result.cleanup);
  }

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }
    for (const cleanup of primitiveCleanups) cleanup();

    disposeOwned(
      root,
      ownedMaterials,
      ownedGeometries,
      loadedTextures
    );
    root.clear();
  };

  return root;
}
